export const DICT = { ar, en };

export function makeT(lang) {
  const d = DICT[lang] || ar;
  return (key, vars) => {
    let s = d[key] ?? DICT.en[key] ?? key;
    if (vars) for (const [k, v] of Object.entries(vars)) s = s.replaceAll(`{${k}}`, v);
    return s;
  };
}
